--

ALTER TABLE public.submission ALTER COLUMN submission_id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.submission_submission_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: submission_value; Type: TABLE; Schema: public; Owner: asrs
--

CREATE TABLE public.submission_value (
    submission_value_id integer NOT NULL,
    submission_id integer NOT NULL,
    value_text text,
    value_number real,
    value_date text,
    value_bool integer,
    value_json text,
    form_question_id integer NOT NULL
);


ALTER TABLE public.submission_value OWNER TO asrs;

--
-- Name: submission_value_submission_value_id_seq; Type: SEQUENCE; Schema: public; Owner: asrs
--

ALTER TABLE public.submission_value ALTER COLUMN submission_value_id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.submission_value_submission_value_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: survey_distribution; Type: TABLE; Schema: public; Owner: asrs
--

CREATE TABLE public.survey_distribution (
    distribution_id integer NOT NULL,
    survey_template_id text NOT NULL,
    title text NOT NULL,
    start_date text NOT NULL,
    end_date text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    recipient_emails text DEFAULT '[]'::text NOT NULL,
    response_count integer DEFAULT 0 NOT NULL,
    created_at text DEFAULT CURRENT_TIMESTAMP,
    created_by_user_id integer,
    CONSTRAINT survey_distribution_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'active'::text, 'closed'::text])))
);


ALTER TABLE public.survey_distribution OWNER TO asrs;

--
-- Name: survey_distribution_distribution_id_seq; Type: SEQUENCE; Schema: public; Owner: asrs
--

ALTER TABLE public.survey_distribution ALTER COLUMN distribution_id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.survey_distribution_distribution_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: surveys; Type: TABLE; Schema: public; Owner: asrs
--

CREATE TABLE public.surveys (
