    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: trend; Type: TABLE; Schema: public; Owner: asrs
--

CREATE TABLE public.trend (
    trend_id integer NOT NULL,
    initiative_id integer NOT NULL,
    trend_key text NOT NULL,
    report_id text,
    attributes text DEFAULT '[]'::text NOT NULL,
    direction text NOT NULL,
    magnitude real DEFAULT 0 NOT NULL,
    time_period text,
    enabled_display integer DEFAULT 1 NOT NULL,
    enabled_calc integer DEFAULT 1 NOT NULL,
    description text,
    CONSTRAINT trend_direction_check CHECK ((direction = ANY (ARRAY['up'::text, 'down'::text, 'stable'::text])))
);


ALTER TABLE public.trend OWNER TO asrs;

